import { http } from '@kit.NetworkKit';
import { DomainBackend } from '../integration/DomainIntegration';

/** Credentials of the account that owns the domains. */
export interface DomainSession {
  authToken: string;
  siteId: string;
}

/**
 * WordPress.com implementation of the domain service.
 *
 * Every call returns a payload that the store understands:
 *  - the domain list answers with `type: success` and the owned domains,
 *  - an account without domains answers with `type: empty`,
 *  - a failed request answers with `type: error` so that the flow can offer a
 *    retry instead of showing a broken screen.
 */
export class WordPressComDomainBackend implements DomainBackend {
  private baseUrl: string;
  private session: DomainSession;

  constructor(session: DomainSession, baseUrl: string = 'https://public-api.wordpress.com') {
    this.session = session;
    this.baseUrl = baseUrl;
  }

  async fetchAllDomains(): Promise<Object> {
    return await this.request(http.RequestMethod.GET, '/rest/v1.1/domains');
  }

  async searchForDomains(query: string): Promise<Object> {
    const path = '/rest/v1.1/domains/suggestions?quantity=20&query=' + encodeURIComponent(query);
    return await this.request(http.RequestMethod.GET, path);
  }

  async createCart(mode: string, domain: string, productId?: number, supportsPrivacy?: boolean): Promise<Object> {
    const body: Record<string, Object> = {
      'domain': domain,
      'mode': mode,
      'product_id': productId === undefined ? 0 : productId,
      'privacy': supportsPrivacy === undefined ? false : supportsPrivacy
    };
    return await this.request(http.RequestMethod.POST, '/rest/v1.1/me/cart', body);
  }

  private async request(method: http.RequestMethod, path: string, body?: Object): Promise<Object> {
    const client = http.createHttp();
    try {
      const options: http.HttpRequestOptions = {
        method: method,
        header: {
          'Authorization': 'Bearer ' + this.session.authToken,
          'Content-Type': 'application/json'
        },
        expectDataType: http.HttpDataType.STRING,
        connectTimeout: 15000,
        readTimeout: 15000
      };
      if (body !== undefined) {
        options.extraData = body;
      }
      const response = await client.request(this.baseUrl + path, options);
      const code = response.responseCode;
      if (code < 200 || code >= 300) {
        return { 'type': 'error', 'code': code };
      }
      const payload = response.result;
      if (typeof payload !== 'string') {
        return { 'type': 'success', 'domains': [] };
      }
      try {
        return JSON.parse(payload) as Object;
      } catch (error) {
        return { 'type': 'success', 'domains': [] };
      }
    } catch (error) {
      return { 'type': 'error' };
    } finally {
      client.destroy();
    }
  }
}

import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import { DomainEffect, DomainLeaf } from '../integration/DomainIntegration';

/**
 * Sink that receives the effects of the domain feature.
 *
 * The leaf is the boundary of the feature: the store reports what happened and
 * the host decides what to do with it. The production leaf keeps the last
 * effects around so that the page can show the current navigation and the
 * diagnostics of the flow.
 */
export class DomainAppLeaf implements DomainLeaf {
  private effects: DomainEffect[] = [];

  async emit(effect: DomainEffect): Promise<void> {
    this.effects.push(effect);
    if (this.effects.length > 64) {
      this.effects.shift();
    }
  }

  /** The effect that was produced last. */
  latest(): DomainEffect | undefined {
    if (this.effects.length === 0) {
      return undefined;
    }
    return this.effects[this.effects.length - 1];
  }

  /** Every effect that was produced so far. */
  all(): DomainEffect[] {
    return this.effects.slice();
  }
}

/** Reads the credentials of the signed in account. */
export class DomainSessionStore {
  private context: common.UIAbilityContext;

  constructor(context: common.UIAbilityContext) {
    this.context = context;
  }

  async read(): Promise<DomainSession> {
    const prefs = await preferences.getPreferences(this.context, 'wordpress_session');
    const authToken = await prefs.get('authToken', '') as string;
    const siteId = await prefs.get('siteId', '') as string;
    return { authToken: authToken, siteId: siteId };
  }
}

/** Credentials of the account that owns the domains. */
export interface DomainSession {
  authToken: string;
  siteId: string;
}

import { common } from '@kit.AbilityKit';
import {
  DomainBackend, DomainEffect, DomainInput, DomainLeaf, DomainPageOwner, DomainSnapshot
} from '../integration/DomainIntegration';
import { DomainStore } from '../model/DomainStore';
import { DomainAppLeaf, DomainSession, DomainSessionStore } from '../service/DomainAppLeaf';
import { WordPressComDomainBackend } from '../service/WordPressComDomainBackend';

/** Backend that reads the account credentials before every remote call. */
class SessionDomainBackend implements DomainBackend {
  private sessions: DomainSessionStore;

  constructor(sessions: DomainSessionStore) {
    this.sessions = sessions;
  }

  private async resolve(): Promise<WordPressComDomainBackend> {
    const session: DomainSession = await this.sessions.read();
    return new WordPressComDomainBackend(session);
  }

  async fetchAllDomains(): Promise<Object> {
    const backend = await this.resolve();
    return await backend.fetchAllDomains();
  }

  async searchForDomains(query: string): Promise<Object> {
    const backend = await this.resolve();
    return await backend.searchForDomains(query);
  }

  async createCart(mode: string, domain: string, productId?: number, supportsPrivacy?: boolean): Promise<Object> {
    const backend = await this.resolve();
    return await backend.createCart(mode, domain, productId, supportsPrivacy);
  }
}

function emptySnapshot(): DomainSnapshot {
  return {
    screen: 'domain_management',
    listState: 'loading',
    searchState: 'idle',
    cartState: 'idle',
    loading: true,
    errorMessage: '',
    searchError: '',
    cartError: '',
    cartProgress: '',
    filterQuery: '',
    searchQuery: '',
    purchaseMode: '',
    selectedDomain: '',
    selectedSiteSlug: '',
    registrationOutcome: '',
    purchaseScreenOpen: false,
    addDomainEnabled: false,
    searchEnabled: false,
    containedWebViewUrl: '',
    externalNavigationUrl: '',
    detailsDomain: '',
    checkoutUrl: '',
    lastPurchasedDomain: '',
    visibleDomains: [],
    proposals: []
  };
}

/**
 * Owner of the domain page. It keeps the store alive for as long as the page
 * is mounted and releases the resources of the feature when the page goes
 * away.
 */
export class MountedDomainPageOwner implements DomainPageOwner {
  private store?: DomainStore;
  private ready: Promise<void> = Promise.resolve();
  private readonly pageOwnerId: string;
  private readonly controllerOwnerId: string;

  constructor(generation: number) {
    this.pageOwnerId = 'domain-page-owner-' + generation.toString();
    this.controllerOwnerId = 'domain-controller-' + generation.toString();
  }

  mount(context: common.UIAbilityContext, input: DomainInput, initialize: boolean): Promise<void> {
    this.ready = DomainStore.create(context, input, initialize).then((value: DomainStore) => {
      this.store = value;
    });
    return this.ready;
  }

  async waitUntilReady(): Promise<void> {
    await this.ready;
  }

  async invoke(name: string, event: Record<string, Object>): Promise<void> {
    await this.ready;
    if (this.store === undefined) {
      throw new Error('Domain store is not mounted');
    }
    await this.store.invoke(name, event);
  }

  currentState(): Record<string, Object> {
    return this.store === undefined ? {} : this.store.currentState();
  }

  /** Typed state of the feature, used by the page. */
  snapshot(): DomainSnapshot {
    return this.store === undefined ? emptySnapshot() : this.store.snapshot();
  }

  /** Releases the store and the timers it owns. */
  async unmount(): Promise<void> {
    await this.ready;
    if (this.store !== undefined) {
      this.store.dispose();
      this.store = undefined;
    }
  }

  ownerId(): string { return this.pageOwnerId; }
  controllerId(): string { return this.controllerOwnerId; }
  storeSource(): string { return 'Index.DomainPageOwner.controller.store'; }
  featureAvailable(): boolean { return this.store !== undefined; }
}

/** Runtime that hands the mounted owner to the page. */
export class DomainPageRuntime {
  private static context?: common.UIAbilityContext;
  private static input?: DomainInput;
  private static current?: MountedDomainPageOwner;
  private static generation: number = 0;
  private static leaf: DomainAppLeaf = new DomainAppLeaf();

  static configure(context: common.UIAbilityContext, input: DomainInput): void {
    DomainPageRuntime.context = context;
    DomainPageRuntime.input = input;
    DomainPageRuntime.current = undefined;
    DomainPageRuntime.generation = 0;
  }

  /** Wires the production service and the production effect sink. */
  static configureDefault(context: common.UIAbilityContext): void {
    const leaf = new DomainAppLeaf();
    const backend = new SessionDomainBackend(new DomainSessionStore(context));
    DomainPageRuntime.leaf = leaf;
    DomainPageRuntime.configure(context, { backend: backend, leaf: leaf });
  }

  static createOwner(): MountedDomainPageOwner {
    const context = DomainPageRuntime.context;
    const input = DomainPageRuntime.input;
    if (context === undefined || input === undefined) {
      throw new Error('Domain runtime is not configured');
    }
    DomainPageRuntime.generation += 1;
    const owner = new MountedDomainPageOwner(DomainPageRuntime.generation);
    DomainPageRuntime.current = owner;
    void owner.mount(context, input, DomainPageRuntime.generation === 1);
    return owner;
  }

  static async waitForOwner(attempt: number = 0): Promise<MountedDomainPageOwner> {
    const owner = DomainPageRuntime.current;
    if (owner !== undefined) {
      await owner.waitUntilReady();
      return owner;
    }
    if (attempt >= 120) {
      throw new Error('Domain page owner mount timed out');
    }
    await new Promise<void>((resolve: () => void) => setTimeout(() => resolve(), 25));
    return DomainPageRuntime.waitForOwner(attempt + 1);
  }

  /** Effect sink of the running feature. */
  static effects(): DomainLeaf {
    return DomainPageRuntime.leaf;
  }

  /** Latest effect that the feature produced. */
  static latestEffect(): DomainEffect | undefined {
    return DomainPageRuntime.leaf.latest();
  }

  /** Releases the mounted owner. */
  static async release(): Promise<void> {
    const owner = DomainPageRuntime.current;
    DomainPageRuntime.current = undefined;
    if (owner !== undefined) {
      await owner.unmount();
    }
  }
}

import { MountedDomainPageOwner, DomainPageRuntime } from './DomainPageOwner';
import {
  DomainCartState, DomainListState, DomainProposal, DomainPurchaseMode, DomainRow, DomainScreen,
  DomainSearchState, DomainSnapshot
} from '../integration/DomainIntegration';

function emptyEvent(): Record<string, Object> { return JSON.parse('{}') as Record<string, Object>; }
function textEvent(key: string, value: string): Record<string, Object> {
  const event = emptyEvent();
  event[key] = value;
  return event;
}

@Entry
@Component
struct Index {
  private owner: MountedDomainPageOwner = DomainPageRuntime.createOwner();
  @State screen: string = DomainScreen.MANAGEMENT;
  @State listState: string = DomainListState.LOADING;
  @State searchState: string = DomainSearchState.IDLE;
  @State cartState: string = DomainCartState.IDLE;
  @State errorMessage: string = '';
  @State searchError: string = '';
  @State cartError: string = '';
  @State cartProgress: string = '';
  @State filterQuery: string = '';
  @State searchQuery: string = '';
  @State purchaseMode: string = '';
  @State selectedDomain: string = '';
  @State selectedSiteSlug: string = '';
  @State registrationOutcome: string = '';
  @State addDomainEnabled: boolean = false;
  @State containedUrl: string = '';
  @State externalUrl: string = '';
  @State detailsDomain: string = '';
  @State checkoutUrl: string = '';
  @State requestedUrl: string = '';
  @State rows: DomainRow[] = [];
  @State proposals: DomainProposal[] = [];
  @State summary: string = '';

  aboutToAppear(): void { void this.refresh(); }
  aboutToDisappear(): void { void this.owner.unmount(); }

  private async refresh(): Promise<void> {
    await this.owner.waitUntilReady();
    this.applySnapshot(this.owner.snapshot());
  }

  private applySnapshot(snapshot: DomainSnapshot): void {
    this.screen = snapshot.screen;
    this.listState = snapshot.listState;
    this.searchState = snapshot.searchState;
    this.cartState = snapshot.cartState;
    this.errorMessage = snapshot.errorMessage;
    this.searchError = snapshot.searchError;
    this.cartError = snapshot.cartError;
    this.cartProgress = snapshot.cartProgress;
    this.filterQuery = snapshot.filterQuery;
    this.searchQuery = snapshot.searchQuery;
    this.purchaseMode = snapshot.purchaseMode;
    this.selectedDomain = snapshot.selectedDomain;
    this.selectedSiteSlug = snapshot.selectedSiteSlug;
    this.registrationOutcome = snapshot.registrationOutcome;
    this.addDomainEnabled = snapshot.addDomainEnabled;
    this.containedUrl = snapshot.containedWebViewUrl;
    this.externalUrl = snapshot.externalNavigationUrl;
    this.detailsDomain = snapshot.detailsDomain;
    this.checkoutUrl = snapshot.checkoutUrl;
    this.rows = snapshot.visibleDomains;
    this.proposals = snapshot.proposals;
    this.summary = JSON.stringify(this.owner.currentState());
  }

  private async run(name: string, event: Record<string, Object>): Promise<void> {
    await this.owner.invoke(name, event);
    await this.refresh();
  }

  build() {
    Column({ space: 12 }) {
      this.Header()
      if (this.screen === DomainScreen.SEARCH) {
        this.SearchBody()
      } else if (this.screen === DomainScreen.PURCHASE) {
        this.PurchaseBody()
      } else if (this.screen === DomainScreen.CHECKOUT) {
        this.CheckoutBody()
      } else if (this.screen === DomainScreen.DETAILS) {
        this.DetailsBody()
      } else {
        this.ManagementBody()
      }
      Text(this.summary).fontSize(10).width('100%')
    }.width('100%').height('100%').padding(16).alignItems(HorizontalAlign.Start)
  }

  @Builder
  Header() {
    Row({ space: 12 }) {
      Text('All Domains').fontSize(26).fontWeight(FontWeight.Bold).layoutWeight(1)
      Button('Refresh').onClick(() => void this.run('openDomainManagement', emptyEvent()))
    }.width('100%')
  }

  @Builder
  ManagementBody() {
    Row({ space: 8 }) {
      TextInput({ text: this.filterQuery, placeholder: 'Filter domains' })
        .layoutWeight(1)
        .onChange((value: string) => {
          this.filterQuery = value;
          void this.run('enterLocalFilter', textEvent('query', value));
        })
      Button('Add domain')
        .enabled(this.addDomainEnabled)
        .onClick(() => void this.run('openDomainManagementThenTapAddDomain', emptyEvent()))
    }.width('100%')

    if (this.listState === DomainListState.LOADING) {
      Row({ space: 8 }) {
        LoadingProgress().width(22).height(22)
        Text('Loading domains').fontSize(15)
      }.width('100%')
    } else if (this.listState === DomainListState.ERROR) {
      Column({ space: 8 }) {
        Text(this.errorMessage).fontSize(15).width('100%')
        Button('Retry').onClick(() => void this.run('tapRetry', emptyEvent()))
      }.width('100%')
    } else if (this.listState === DomainListState.EMPTY) {
      Column({ space: 8 }) {
        Text('You do not have any domains yet.').fontSize(15).width('100%')
        Button('Find a domain').onClick(() => void this.run('openDomainManagementThenTapFindDomain', emptyEvent()))
      }.width('100%')
    } else {
      if (this.rows.length === 0) {
        Text('No domains match your filter.').fontSize(15).width('100%')
      }
      ForEach(this.rows, (row: DomainRow) => {
        this.DomainRowView(row)
      }, (row: DomainRow) => row.domain)
    }
  }

  @Builder
  DomainRowView(row: DomainRow) {
    Column({ space: 4 }) {
      Text(row.domain).fontSize(17).fontWeight(FontWeight.Medium).width('100%')
      Text(row.siteTitle).fontSize(13).width('100%')
      Text(row.status + (row.expiry.length > 0 ? ' · expires ' + row.expiry : '')).fontSize(12).width('100%')
      Button('Details')
        .onClick(() => void this.run('openDetails', textEvent('domain', row.domain)))
    }.width('100%').padding(10).backgroundColor('#F2F2F7').borderRadius(8)
  }

  @Builder
  SearchBody() {
    Text('Find a new domain').fontSize(20).fontWeight(FontWeight.Bold).width('100%')
    TextInput({ text: this.searchQuery, placeholder: 'Search for a domain' })
      .width('100%')
      .onChange((value: string) => {
        this.searchQuery = value;
        void this.run('enterSearchQuery', textEvent('query', value));
      })
    if (this.searchState === DomainSearchState.LOADING) {
      Row({ space: 8 }) {
        LoadingProgress().width(22).height(22)
        Text('Searching for domains').fontSize(15)
      }.width('100%')
    } else if (this.searchState === DomainSearchState.ERROR) {
      Column({ space: 8 }) {
        Text(this.searchError).fontSize(15).width('100%')
        Button('Retry').onClick(() => void this.run('retrySearch', emptyEvent()))
      }.width('100%')
    } else if (this.searchState === DomainSearchState.EMPTY) {
      Text('No domains found for this search.').fontSize(15).width('100%')
    } else {
      ForEach(this.proposals, (proposal: DomainProposal) => {
        this.ProposalView(proposal)
      }, (proposal: DomainProposal) => proposal.domain)
    }
    Button('Back to domains').onClick(() => void this.run('closeDomainSearch', emptyEvent()))
  }

  @Builder
  ProposalView(proposal: DomainProposal) {
    Column({ space: 4 }) {
      Text(proposal.domain).fontSize(17).fontWeight(FontWeight.Medium).width('100%')
      Text(proposal.price.length > 0 ? proposal.price : 'Price on request').fontSize(13).width('100%')
      if (proposal.salePrice.length > 0) {
        Text(proposal.salePrice).fontSize(13).width('100%')
      }
      if (proposal.supportsPrivacy) {
        Text('Privacy protection available').fontSize(12).width('100%')
      }
      Button('Buy').onClick(() => void this.run('tapProposedDomain', textEvent('domain', proposal.domain)))
    }.width('100%').padding(10).backgroundColor('#F2F2F7').borderRadius(8)
  }

  @Builder
  PurchaseBody() {
    Text('Purchase ' + this.selectedDomain).fontSize(20).fontWeight(FontWeight.Bold).width('100%')
    Text('Choose how you want to use this domain.').fontSize(14).width('100%')
    Button('Buy this domain only')
      .enabled(this.cartState !== DomainCartState.SUBMITTING)
      .onClick(() => void this.run('selectNewDomainMode', emptyEvent()))
    if (this.rows.length > 0) {
      Text('Or attach it to an existing site').fontSize(14).width('100%')
      ForEach(this.rows, (row: DomainRow) => {
        Button('Use ' + row.siteSlug)
          .enabled(this.cartState !== DomainCartState.SUBMITTING)
          .onClick(() => void this.run('selectExistingSiteMode', textEvent('siteSlug', row.siteSlug)))
      }, (row: DomainRow) => row.domain)
    }
    if (this.cartState === DomainCartState.SUBMITTING) {
      Row({ space: 8 }) {
        LoadingProgress().width(22).height(22)
        Text(this.cartProgress).fontSize(14)
      }.width('100%')
    }
    if (this.cartState === DomainCartState.ERROR) {
      Column({ space: 8 }) {
        Text(this.cartError).fontSize(15).width('100%')
        Button('Try again').onClick(() => void this.run(this.retryAction(), emptyEvent()))
      }.width('100%')
    }
    if (this.registrationOutcome === 'invalid') {
      Text('The checkout result was missing or invalid.').fontSize(15).width('100%')
    }
  }

  private retryAction(): string {
    if (this.purchaseMode === DomainPurchaseMode.EXISTING_SITE) {
      return 'acknowledgeCartErrorThenRetryExistingSite';
    }
    return 'acknowledgeCartErrorThenRetryNewDomain';
  }

  @Builder
  CheckoutBody() {
    Text('Checkout').fontSize(20).fontWeight(FontWeight.Bold).width('100%')
    Text(this.selectedDomain).fontSize(16).width('100%')
    Text(this.checkoutUrl).fontSize(12).width('100%')
    Button('Complete purchase').onClick(() => void this.run('completeCheckout', emptyEvent()))
    Button('Cancel checkout').onClick(() => void this.run('cancelCheckout', emptyEvent()))
  }

  @Builder
  DetailsBody() {
    Text('Domain details').fontSize(20).fontWeight(FontWeight.Bold).width('100%')
    Text(this.detailsDomain).fontSize(16).width('100%')
    Text(this.containedUrl).fontSize(12).width('100%')
    if (this.externalUrl.length > 0) {
      Text('Opened outside the app: ' + this.externalUrl).fontSize(12).width('100%')
    }
    TextInput({ text: this.requestedUrl, placeholder: 'Address to open' })
      .width('100%')
      .onChange((value: string) => { this.requestedUrl = value; })
    Button('Open address')
      .onClick(() => void this.run('requestDetailsNavigation', textEvent('requestedUrl', this.requestedUrl)))
    Button('Back to domains').onClick(() => void this.run('openDomainManagement', emptyEvent()))
  }
}

