/**
 * Reloads the domain list. When the reload fails the list that is already
 * on screen stays visible, a failed refresh never empties the screen.
 */
private async refreshDomains(): Promise<void> {
  const previousState = this.listState;
  const previousVisible = this.visibleRows.slice();
  await this.loadDomains();
  if (this.listState === DomainListState.ERROR && previousVisible.length > 0) {
    this.listState = previousState;
    this.visibleRows = previousVisible;
    this.setState('listState', this.listState);
    this.setState('loading', false);
    this.setState('errorMessage', 'We could not refresh your domains.');
    this.setState('retryAvailable', true);
    this.setState('addDomainEnabled', true);
    this.setState('findDomainEnabled', true);
    this.setState('searchEnabled', true);
    this.publishRows();
  }
}

