input.newString:
private cartProgressLabel(mode: string): string {
  if (mode === DomainPurchaseMode.EXISTING_SITE) {
    return 'Adding the domain to your site';
  }
  return 'Preparing the domain purchase';
}

/** A cart answers with success when it carries a checkout to continue with. */
private cartSucceeded(response: Object): boolean {
  const record = asRecord(response);
  if (record === undefined) {
    return false;
  }
  const type = asText(record['type']).toLowerCase();
  if (type === 'success' || type === 'ok' || type === 'complete') {
    return true;
  }
  if (type.length > 0) {
    return false;
  }
  return hasEntry(record['checkoutToken']) || hasEntry(record['token']) ||
    hasEntry(record['checkoutUrl']) || hasEntry(record['url']);
}

